<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\GdprConsent\Infrastructure\Driver\Rest;

use DateTime;
use Throwable;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\GdprConsentRecord;
use Civi\Lughauth\Features\Oidc\GdprConsent\Domain\Gateway\GdprConsentGateway;

final class MeConsentsGrantController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly Context $context,
        private readonly SqlTemplate $sql,
        private readonly GdprConsentGateway $gateway,
    ) {
    }

    #[OA\Put(
        path: '/api/me/consents/{purposeKey}',
        summary: 'Grant or revoke a GDPR consent purpose',
        tags: ['Me - GDPR Consents'],
        security: [['bearerAuth' => []]],
        parameters: [
            new OA\PathParameter(name: 'purposeKey', required: true, schema: new OA\Schema(type: 'string')),
        ],
        requestBody: new OA\RequestBody(
            required: true,
            content: new OA\JsonContent(properties: [
                new OA\Property(property: 'granted', type: 'boolean'),
            ])
        ),
        responses: [
            new OA\Response(response: 200, description: 'OK', content: new OA\JsonContent(ref: '#/components/schemas/MeConsentApiDTO')),
            new OA\Response(response: 401, description: 'Unauthorized'),
            new OA\Response(response: 404, description: 'Purpose not found'),
            new OA\Response(response: 422, description: 'Required purpose cannot be revoked'),
        ]
    )]
    public function grant(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug('Grant me/consents/{purposeKey}');
        $span = $this->startSpan('Grant me/consents/{purposeKey}');
        try {
            $identity = $this->context->getIdentity();
            if ($identity->anonymous || null === $identity->id) {
                throw new UnauthorizedException();
            }

            $purposeKey = $args['purposeKey'] ?? '';
            $body = (array) ($request->getParsedBody() ?? []);
            $granted = (bool) ($body['granted'] ?? false);

            $serverParams = $request->getServerParams();
            $ipAddress = (string) ($serverParams['REMOTE_ADDR'] ?? '');
            $userAgent = (string) ($request->getHeaderLine('User-Agent') ?? '');

            $this->sql->begin();
            try {
                $consent = $this->gateway->grantConsent(
                    $identity->id,
                    $identity->tenant ?? '',
                    $purposeKey,
                    $granted,
                    $ipAddress,
                    $userAgent
                );
                $this->sql->commit();
            } finally {
                $this->sql->close();
            }

            $encoded = json_encode($this->mapRecord($consent, $purposeKey));
            $response->getBody()->write($encoded !== false ? $encoded : '{}');
            return $response->withStatus(200)->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapRecord(GdprConsentRecord $consent, string $purposeKey): MeConsentApiDTO
    {
        $dto = new MeConsentApiDTO();
        $dto->purposeUid = $consent->purposeUid;
        $dto->purposeKey = $purposeKey;
        $dto->title = $consent->title;
        $dto->description = $consent->description;
        $dto->required = $consent->required;
        $dto->granted = $consent->granted;
        $dto->decisionAt = $consent->decisionAt?->format(DateTime::ATOM);
        return $dto;
    }
}
